    {
      "name": "Finsupp.le_weight_of_ne_zero",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {w : σ → M},\n  (∀ (s : σ), 0 ≤ w s) → ∀ {s : σ} {f : σ →₀ ℕ}, f s ≠ 0 → w s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "Finsupp.le_weight",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} (w : σ → ℕ) {s : σ}, w s ≠ 0 → ∀ (f : σ →₀ ℕ), f s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "MvPowerSeries.min_weightedOrder_le_add",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R},\n  min (MvPowerSeries.weightedOrder w f) (MvPowerSeries.weightedOrder w g) ≤ MvPowerSeries.weightedOrder w (f + g)"
    },
    {
      "name": "Finsupp.le_weight_of_ne_zero'",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M]\n  [CanonicallyOrderedAdd M] (w : σ → M) {s : σ} {f : σ →₀ ℕ}, f s ≠ 0 → w s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R},\n  MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)"
    },
    {
      "name": "MvPowerSeries.weightedOrder_add_of_weightedOrder_ne",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R},\n  MvPowerSeries.weightedOrder w f ≠ MvPowerSeries.weightedOrder w g →\n    MvPowerSeries.weightedOrder w (f + g) = min (MvPowerSeries.weightedOrder w f) (MvPowerSeries.weightedOrder w g)"
    }
  ]
}

