      "module_name": "Mathlib.RingTheory.PowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (φ ψ : PowerSeries R), min φ.order ψ.order ≤ (φ + ψ).order"
    },
    {
      "name": "meromorphicOrderAt_add",
      "module_name": "Mathlib.Analysis.Meromorphic.Order",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2} [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {f₁ f₂ : 𝕜 → E} {x : 𝕜},\n  MeromorphicAt f₁ x →\n    MeromorphicAt f₂ x → min (meromorphicOrderAt f₁ x) (meromorphicOrderAt f₂ x) ≤ meromorphicOrderAt (f₁ + f₂) x"
    },
    {
      "name": "analyticOrderAt_add_of_ne",
      "module_name": "Mathlib.Analysis.Analytic.Order",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {f g : 𝕜 → E} {z₀ : 𝕜},\n  analyticOrderAt f z₀ ≠ analyticOrderAt g z₀ →\n    analyticOrderAt (f + g) z₀ = min (analyticOrderAt f z₀) (analyticOrderAt g z₀)"
    }
  ]
}

